def forward(self, x):
    bsz, c, h, w = x.shape
    if h * w == 1:
        return x.view(bsz, c)
    z = x.reshape(bsz * c, 1, h, w)
    zn = (z - z.mean((2, 3), keepdim=True)) / (z.std((2, 3), keepdim=True) + 1e-5)
    logits = F.conv2d(zn, self.w, self.b, padding=1) + self.t.clamp(-6.0, 6.0) * zn
    a = torch.softmax(logits.flatten(1), dim=1).view_as(z)
